head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = 'ULDSTF39204.xml';
scwin.v_up_schdl_adm_itm_tp_cd = "";
scwin.v_up_schdl_adm_itm_tp_nm = "";
scwin.v_ldMktTpCd = "";
scwin.toDay = "";
scwin.txb_date = "";
scwin.v_cdNm = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_save = function() {
    MxDataSet.setCellData(1, "UP_SCHDL_ADM_ITM_TP_CD", scwin.v_up_schdl_adm_itm_tp_cd);
    MxDataSet.setCellData(1, "LD_MKT_TP_CD", scwin.v_ldMktTpCd);
    MxDataSet.setCellData(1, "SCHDL_ADM_ITM_TP_CD", $c.cp.valueOfIndex(cmb_schdl_adm_itm_tp_cd, "SCHDL_ADM_ITM_TP_CD", cmb_schdl_adm_itm_tp_cd.getSelectedIndex()));
    MxDataSet.setCellData(1, "CD_NM", txt_cd_nm.getValue());
    scwin.v_cdNm = txt_cd_nm.getValue();
    if (checkbox_1.checked == true) {
        MxDataSet.setCellData(1, "DEP_CD", "0");
    } else {
        MxDataSet.setCellData(1, "DEP_CD", $c.cp.valueOfIndex(cmb_dep_cd, "value", cmb_dep_cd.getSelectedIndex()));
    }
    if (!scwin.fn_saveChk()) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    MxLogicalTr.Action = "/DisclosureSchedule.do?method=saveAdmItmTpCd";
    MxLogicalTr.KeyName = "toinb_dataid4";
    MxLogicalTr.KeyValue = "JSP(I:pInputMaster=MxDataSet)";
    MxLogicalTr.Post();
};
scwin.fn_saveChk = function() {
    //상위일정관리항목유형코드
    if (txt_cd_nm.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "코드명");
        $c.win.alert(msg);
        txt_cd_nm.focus();
        return false;
    }
    return true;
};
scwin.gform_onload = function() {
    scwin.v_up_schdl_adm_itm_tp_cd = $c.frame.path("../").scwin.v_up_schdl_adm_itm_tp_cd;
    scwin.v_up_schdl_adm_itm_tp_nm = $c.frame.path("../").scwin.v_up_schdl_adm_itm_tp_nm;
    scwin.v_ldMktTpCd = $c.frame.path("../").scwin.v_ldMktTpCd;
    if (scwin.v_ldMktTpCd == "1") {
        txt_ld_mkt_tp_nm.setValue("유가");
    } else if (scwin.v_ldMktTpCd == "2") {
        txt_ld_mkt_tp_nm.setValue("코스닥");
    } else if (scwin.v_ldMktTpCd == "6") {
        txt_ld_mkt_tp_nm.setValue("코넥스");
    } else if (scwin.v_ldMktTpCd == "4") {
        txt_ld_mkt_tp_nm.setValue("채권");
    }
    txt_up_schdl_adm_itm_tp_cd.setValue(scwin.v_up_schdl_adm_itm_tp_cd);
    txt_up_schdl_adm_itm_tp_nm.setValue(scwin.v_up_schdl_adm_itm_tp_nm);
    txt_up_schdl_adm_itm_tp_cd.style.display = "none";
    var url = "/DisclosureSchedule.do?method=listEmptySchdlTpCd";
    url += "&LD_MKT_TP_CD=" + scwin.v_ldMktTpCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_schdl_tp_cd.DataID = encodeURI(url);
    MxDataSet_schdl_tp_cd.reset();
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LIST_ADM_ITM_TP_CD"; //상위일정관리항목유형코드
    MxDataSet.reset();
    var toDay = '';
    var clientnow = new Date();

    /* 오늘 날짜를 구한다 */
    var curYear = clientnow.getYear();
    var curMonth = (clientnow.getMonth()) + 1;
    var curDay = clientnow.getDate();
    if (curMonth <= 9) {
        curMonth = "0" + curMonth;
    }
    if (curDay <= 9) {
        curDay = "0" + curDay;
    }
    scwin.txb_date = curYear + "" + curMonth + "" + curDay;

    //var url = "/bzchklist.do?method=searchBzChkList&inputMessageId=bzchklist&outputMessageId=bzchklist&BAS_DD="+txb_date+"&CHK_BZ_TP_CD=00" +"&SCREN_ID="  + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //MxDataSet_dep_cd.DataID =  encodeURI(url);
    //MxDataSet_dep_cd.reset();

    checkbox_1.setValue(1);
    cmb_dep_cd.style.display = "none";
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.checkbox_1_onclick = function() {
    if (cmb_dep_cd.style.display == "") {
        cmb_dep_cd.style.display = "none";
    } else {
        cmb_dep_cd.style.display = "";
    }
};
scwin.MxLogicalTr_OnSuccess = async function() {
    $c.win.alert('저장이 완료되었습니다.');
    $c.frame.path("../").fn_ReSearch(scwin.v_cdNm);
    await $c.frame.CloseFrame();
};
scwin.MxLogicalTr_OnFail = function() {
    $c.win.alert('저장에 실패했습니다.');
};
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    MxDataSet.insertRow();
};
scwin.MxDataSet_schdl_tp_cd_OnLoadError = function() {
    $c.stf.alert_error(MxDataSet_schdl_tp_cd);
};
